  function formErrors(){const f=s.form,errors=[];if(!f.customer.trim())errors.push('请选择对应客户。');if(!f.needDate)errors.push('请选择客户要货时间。');if(f.payment==='credit'&&(!Number.isInteger(Number(f.paymentDays))||Number(f.paymentDays)<1||Number(f.paymentDays)>365))errors.push('请填写1至365天的账期。');if(f.payment.startsWith('deposit')&&(!Number.isFinite(Number(f.deposit))||Number(f.deposit)<=0||Number(f.deposit)>latest.payable))errors.push('订金须大于0且不超过订单总金额。');if(f.packageSource==='custom'&&f.packing==='barrel'){if(selected().some(r=>!r.customSpec?.trim()||!Number.isFinite(Number(r.customWeight??product(r.id).weightKg))||Number(r.customWeight??product(r.id).weightKg)<=0))errors.push('请填写定制包装容积及有效净重。');}return errors;}
  function saveOrder(status){expire();if(s.editing&&s.orders.find(o=>o.id===s.editing)?.status!=='intent'){toast('该意向单已处理，请重新下单。');changePage('orders');return;}refreshForm();const errors=[...latest.errors,...formErrors()];if(errors.length){$('spFormFeedback').hidden=false;$('spFormFeedback').className='sp-feedback error';$('spFormFeedback').textContent=errors.join(' ');$('spFormFeedback').scrollIntoView({block:'center',behavior:'smooth'});return;}if(status==='formal'){dialog('提示','<div class="sp-confirm-message"><span class="sp-confirm-icon">!</span><strong>是否提交该意向单为正式订单</strong></div>',button('取消','data-sp-close')+button('确定','id="spConfirmAction"',true),'compact');confirmAction=()=>{closeDialog();commitOrder(status);};}else commitOrder(status);}
  function commitOrder(status){expire();if(s.editing&&s.orders.find(o=>o.id===s.editing)?.status!=='intent'){toast('该意向单已处理，请重新下单。');changePage('orders');return;}refreshForm();if(!latest.valid||formErrors().length)return;const now=Date.now(),old=s.orders.find(o=>o.id===s.editing),id=old?.id||'YX'+localDate().replaceAll('-','')+'-'+String(s.orders.length+1).padStart(3,'0');const totals=structuredClone(latest);totals.rows.forEach(r=>r.reservedTons=Math.min(r.tons,r.stockTons));const o={...old,id,status,createdAt:old?.createdAt||now,expiresAt:old?.expiresAt??now+86400000,customer:s.form.customer.trim(),salesperson:'张明',orderType:orderType(selected()),form:structuredClone(s.form),needDate:s.form.needDate,delivery:s.form.delivery,address:s.form.address,remark:s.form.remark,lines:totals.rows,totals,paymentStatus:'unpaid',logs:[...(old?.logs||[]),{time:now,action:old?'修改意向单':status==='formal'?'报价校验通过，提交正式订单':'保存意向单，库存预占24小时'}]};if(status==='formal'){o.formalId=id.replace('YX','XS');o.convertedAt=now;}if(old)s.orders[s.orders.indexOf(old)]=o;else s.orders.unshift(o);s.cart=s.cart.filter(r=>!s.formIds.includes(r.id));s.formIds=[];s.editing=null;s.orderTab=status;persist();changePage('orders');toast(status==='formal'?'订单提交成功。':'意向单已保存，库存预占24小时。');}
