  function filteredOrders(){const f=s.orderFilters;return s.orders.filter(o=>(s.orderTab==='all'||o.status===s.orderTab||(s.orderTab==='cancelled'&&o.status==='expired'))&&(!f.payment||(o.paymentStatus||'unpaid')===f.payment)&&(!f.type||(o.orderType||orderType(o.lines))===f.type)&&(!f.customer||o.customer.includes(f.customer))&&(!f.salesperson||(o.salesperson||'张明').includes(f.salesperson))&&(!f.search||`${o.id} ${o.formalId||''}`.includes(f.search))&&(!f.start||new Date(o.createdAt).toISOString().slice(0,10)>=f.start)&&(!f.end||new Date(o.createdAt).toISOString().slice(0,10)<=f.end));}
