    $('spOrderFilters').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);for(const k of ['payment','type','customer','salesperson','start','end'])f[k]=String(data.get(k)||'').trim();renderOrders();};$('spOrderFilters').onreset=e=>{e.preventDefault();Object.keys(f).forEach(k=>f[k]='');renderOrders();};$('spSearchOrders').onclick=()=>{f.search=$('spOrderSearch').value.trim();renderOrders();};$('spOrderSearch').onkeydown=e=>{if(e.key==='Enter')$('spSearchOrders').click();};$('spExport').onclick=exportOrders;$('spColumns').onclick=()=>dialog('列设置',Object.entries(columnNames).map(([k,n])=>`<label style="display:block;margin:12px"><input class="sp-check" type="checkbox" data-sp-column="${k}" ${show(k)?'checked':''}> ${n}</label>`).join(''),button('完成','id="spApplyColumns"',true));$('spSelectOrders').onchange=e=>{root.querySelectorAll('[data-sp-order-check]').forEach(el=>el.checked=e.target.checked);updateSelection();};
