  function updateSelection(){$('spSelectedOrders').textContent=`已选${root.querySelectorAll('[data-sp-order-check]:checked').length}个`;}
  function exportOrders(){const checked=[...root.querySelectorAll('[data-sp-order-check]:checked')].map(e=>e.dataset.spOrderCheck);const list=filteredOrders().filter(o=>!checked.length||checked.includes(o.id));if(!list.length)return toast('没有可导出的订单。');const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=[['订单编号','客户','订单类型','状态','总金额','下单日期'],...list.map(o=>[o.formalId||o.id,o.customer,o.orderType||orderType(o.lines),statusText[o.status],o.totals.payable,date(o.createdAt)])].map(r=>r.map(safe).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='销售订单.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
